#include <iostream>
#include <string>
using namespace std;

int main() {
    cout << "--- Function Overloading Basics ---" << endl;

    // Overloaded functions (same name, different parameters)
    auto display = [](int x) {
        cout << "Integer: " << x << endl;
    };

    auto display = [](double x) {
        cout << "Double: " << x << endl;
    };

    auto display = [](string x) {
        cout << "String: " << x << endl;
    };

    // Different parameter types
    cout << "Different types:" << endl;
    display(10);          // Calls int version
    display(3.14);        // Calls double version
    display("Hello");     // Calls string version

    cout << "\n--- Without Overloading (Problem) ---" << endl;

    // Without overloading - messy!
    auto addInt = [](int a, int b) { return a + b; };
    auto addDouble = [](double a, double b) { return a + b; };

    cout << "Int sum: " << addInt(5, 3) << endl;
    cout << "Double sum: " << addDouble(5.5, 3.2) << endl;

    cout << "\n--- With Overloading (Solution) ---" << endl;

    // With overloading - clean!
    auto add = [](int a, int b) { return a + b; };
    auto add = [](double a, double b) { return a + b; };

    cout << "Int sum: " << add(5, 3) << endl;
    cout << "Double sum: " << add(5.5, 3.2) << endl;

    cout << "\n--- Different Number of Parameters ---" << endl;

    // Different parameter counts
    auto calculate = [](int a, int b) {
        return a + b;
    };

    auto calculate = [](int a, int b, int c) {
        return a + b + c;
    };

    auto calculate = [](int a, int b, int c, int d) {
        return a + b + c + d;
    };

    cout << "2 numbers: " << calculate(10, 20) << endl;
    cout << "3 numbers: " << calculate(10, 20, 30) << endl;
    cout << "4 numbers: " << calculate(10, 20, 30, 40) << endl;

    cout << "\n--- Practical Examples ---" << endl;

    // Area calculations
    auto area = [](int side) {  // Square
        return side * side;
    };

    auto area = [](int length, int width) {  // Rectangle
        return length * width;
    };

    auto area = [](double radius) {  // Circle
        return 3.14159 * radius * radius;
    };

    cout << "Area calculations:" << endl;
    cout << "Square (side=5): " << area(5) << endl;
    cout << "Rectangle (4x6): " << area(4, 6) << endl;
    cout << "Circle (radius=3): " << area(3.0) << endl;

    cout << "\n--- Print Function Overloading ---" << endl;

    // Print different data types
    auto printData = [](int value) {
        cout << "Integer: " << value << endl;
    };

    auto printData = [](double value) {
        cout << "Double: " << value << endl;
    };

    auto printData = [](bool value) {
        cout << "Boolean: " << (value ? "true" : "false") << endl;
    };

    auto printData = [](string value) {
        cout << "String: " << value << endl;
    };

    printData(42);
    printData(3.14159);
    printData(true);
    printData("C++ Programming");

    cout << "\n--- Rules of Overloading ---" << endl;
    cout << "1. Functions must have same name" << endl;
    cout << "2. Must differ in: " << endl;
    cout << "   - Number of parameters" << endl;
    cout << "   - Type of parameters" << endl;
    cout << "   - Order of parameters" << endl;
    cout << "3. Return type alone is NOT enough" << endl;

    return 0;
}

#include <iostream>
using namespace std;

// Global variable - accessible everywhere
int globalVar = 100;

void demonstrateScope() {
    cout << "--- Inside demonstrateScope() ---" << endl;

    // Local variable - only in this function
    int localVar = 50;

    cout << "Local variable: " << localVar << endl;
    cout << "Can access global: " << globalVar << endl;

    // Block scope (inside {})
    {
        int blockVar = 25;
        cout << "\nInside block:" << endl;
        cout << "Block variable: " << blockVar << endl;
        cout << "Can access local: " << localVar << endl;
        cout << "Can access global: " << globalVar << endl;
    }

    // blockVar is not accessible here
    // cout << blockVar; // ERROR

    cout << "\nBlock ended - blockVar destroyed" << endl;
}

void anotherFunction() {
    cout << "\n--- Inside anotherFunction() ---" << endl;

    // This localVar is different from demonstrateScope's localVar
    int localVar = 999;
    cout << "My own localVar: " << localVar << endl;
    cout << "Global variable: " << globalVar << endl;

    // Cannot access demonstrateScope's localVar
    // cout << localVarFromOtherFunction; // ERROR
}

void nameConflict() {
    cout << "\n--- Name Conflict Example ---" << endl;

    // Local variable with same name as global
    int globalVar = 777; // Different variable!

    cout << "Local globalVar: " << globalVar << endl;
    cout << "Real globalVar (using ::): " << ::globalVar << endl;
}

void modifyGlobal() {
    cout << "\n--- Modifying Global Variable ---" << endl;

    cout << "Before modification: " << globalVar << endl;
    globalVar = 200; // Changes the real global variable
    cout << "After modification: " << globalVar << endl;
}

int main() {
    cout << "=== C++ Variable Scope Demo ===" << endl;

    cout << "\nIn main function:" << endl;
    cout << "Global variable: " << globalVar << endl;

    // Cannot access local variables from other functions
    // cout << localVar; // ERROR

    demonstrateScope();
    anotherFunction();
    nameConflict();
    modifyGlobal();

    cout << "\n--- Back in main() ---" << endl;
    cout << "Global is now: " << globalVar << endl;

    // Function parameter scope
    cout << "\n--- Parameter Scope ---" << endl;
    auto processNumber = [](int number) { // number is local to lambda
        cout << "Processing: " << number << endl;
        number = number * 2; // Changes local copy
        cout << "After processing: " << number << endl;
    };

    int myNumber = 10;
    cout << "Before calling function: " << myNumber << endl;
    processNumber(myNumber);
    cout << "After function (original unchanged): " << myNumber << endl;

    // Loop variable scope
    cout << "\n--- Loop Variable Scope ---" << endl;
    for (int i = 0; i < 3; i++) {
        int loopVar = i * 10; // Created each iteration
        cout << "Iteration " << i << ": loopVar = " << loopVar << endl;
    }
    // i and loopVar not accessible here
    // cout << i; // ERROR

    // Static local variable
    cout << "\n--- Static Variable ---" << endl;
    auto counter = []() {
        static int count = 0; // Persists between calls
        count++;
        cout << "Call count: " << count << endl;
    };

    counter();
    counter();
    counter();

    cout << "\n--- Scope Best Practices ---" << endl;
    cout << "1. Use local variables when possible" << endl;
    cout << "2. Avoid global variables unless necessary" << endl;
    cout << "3. Don't reuse names unnecessarily" << endl;
    cout << "4. Keep scope as small as possible" << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <functional>
using namespace std;

int main() {
    cout << "=== C++ Lambda Functions ===" << endl;

    cout << "\n--- Basic Lambda Syntax ---" << endl;

    // Basic lambda (no parameters, no capture)
    auto greet = []() {
        cout << "Hello from lambda!" << endl;
    };

    greet();

    // Lambda with parameters
    auto add = [](int a, int b) {
        return a + b;
    };

    cout << "5 + 3 = " << add(5, 3) << endl;

    // Lambda with explicit return type
    auto divide = [](double a, double b) -> double {
        if (b == 0) return 0;
        return a / b;
    };

    cout << "10 / 3 = " << divide(10, 3) << endl;

    cout << "\n--- Capture Clause [] ---" << endl;

    int x = 10;
    int y = 20;

    // Capture by value [x] (copy)
    auto showX = [x]() {
        cout << "Captured x (by value): " << x << endl;
        // x = 5; // ERROR: Cannot modify captured by value
    };

    // Capture by reference [&y]
    auto modifyY = [&y]() {
        y = 99;
        cout << "Modified y to: " << y << endl;
    };

    showX();
    cout << "Original x: " << x << endl;

    modifyY();
    cout << "Original y is now: " << y << endl;

    // Capture all by value [=]
    auto captureAllByValue = [=]() {
        cout << "All by value - x: " << x << ", y: " << y << endl;
    };

    // Capture all by reference [&]
    auto captureAllByRef = [&]() {
        x = 100;
        y = 200;
        cout << "Modified via reference" << endl;
    };

    captureAllByValue();
    captureAllByRef();
    cout << "After reference capture - x: " << x << ", y: " << y << endl;

    cout << "\n--- Lambdas with STL Algorithms ---" << endl;

    vector<int> numbers = {5, 2, 8, 1, 9, 3};

    // Sort with lambda
    sort(numbers.begin(), numbers.end(), [](int a, int b) {
        return a > b;  // Descending order
    });

    cout << "Sorted descending: ";
    for (int n : numbers) cout << n << " ";
    cout << endl;

    // Find with lambda
    auto it = find_if(numbers.begin(), numbers.end(), [](int n) {
        return n > 5;
    });

    if (it != numbers.end()) {
        cout << "First number > 5: " << *it << endl;
    }

    // Count with lambda
    int count = count_if(numbers.begin(), numbers.end(), [](int n) {
        return n % 2 == 0;  // Count even numbers
    });

    cout << "Even numbers count: " << count << endl;

    cout << "\n--- Passing Lambdas to Functions ---" << endl;

    // Function that accepts lambda
    auto processNumbers = [](const vector<int>& nums, function<void(int)> processor) {
        for (int n : nums) {
            processor(n);
        }
    };

    cout << "Processing numbers:" << endl;
    processNumbers(numbers, [](int n) {
        cout << "Number: " << n << endl;
    });

    cout << "\n--- Lambda in Loops ---" << endl;

    for (int i = 1; i <= 3; i++) {
        // Lambda capturing loop variable
        auto multiplier = [i](int value) {
            return value * i;
        };

        cout << i << " times table: ";
        for (int j = 1; j <= 3; j++) {
            cout << multiplier(j) << " ";
        }
        cout << endl;
    }

    cout << "\n--- Mutable Lambdas ---" << endl;

    // mutable allows modifying captured by value variables
    auto counter = [count = 0]() mutable {
        return ++count;
    };

    cout << "Counter: " << counter() << endl;
    cout << "Counter: " << counter() << endl;
    cout << "Counter: " << counter() << endl;

    cout << "\n--- Immediate Invocation ---" << endl;

    // Define and call immediately
    int result = [](int a, int b) { return a * b; }(6, 7);
    cout << "6 * 7 = " << result << endl;

    cout << "\n--- Lambda vs Regular Function ---" << endl;
    cout << "Use lambda when:" << endl;
    cout << "1. Short, one-time use" << endl;
    cout << "2. Need to capture local variables" << endl;
    cout << "3. Passing to algorithms (sort, find, etc.)" << endl;
    cout << "\nUse regular function when:" << endl;
    cout << "1. Reusable in multiple places" << endl;
    cout << "2. Complex logic" << endl;
    cout << "3. Need clear name for documentation" << endl;

    return 0;
}

