#include <iostream>
#include <string>
using namespace std;

class BankAccount {
private:
    string accountNumber;
    double balance;

public:
    // Constructor overloading
    BankAccount() {  // Default constructor
        accountNumber = "Unknown";
        balance = 0.0;
    }

    BankAccount(string accNum, double initialBalance) {  // Parameterized constructor
        accountNumber = accNum;
        balance = initialBalance;
    }

    // Getter methods
    string getAccountNumber() {
        return accountNumber;
    }

    double getBalance() {
        return balance;
    }

    // Setter methods with validation
    void setBalance(double newBalance) {
        if (newBalance >= 0) {
            balance = newBalance;
        } else {
            cout << "Error: Balance cannot be negative!" << endl;
        }
    }

    // Business methods
    void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            cout << "Deposited: $" << amount << endl;
        } else {
            cout << "Error: Deposit amount must be positive!" << endl;
        }
    }

    void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            cout << "Withdrawn: $" << amount << endl;
        } else {
            cout << "Error: Invalid withdrawal amount!" << endl;
        }
    }

    // Friend function declaration
    friend void displayAccountDetails(BankAccount account);
};

// Friend function definition
void displayAccountDetails(BankAccount account) {
    cout << "Friend Function - Account: " << account.accountNumber 
         << ", Balance: $" << account.balance << endl;
}

int main() {
    // Using different constructors
    BankAccount account1;  // Default constructor
    BankAccount account2("ACC123", 1000.0);  // Parameterized constructor

    // Using encapsulation
    account1.deposit(500.0);
    account2.withdraw(200.0);

    cout << "Account 1 Balance: $" << account1.getBalance() << endl;
    cout << "Account 2 Balance: $" << account2.getBalance() << endl;

    // Using friend function
    displayAccountDetails(account2);

    return 0;
}

