#include <iostream>
#include <string>
using namespace std;

// Base class
class Animal {
protected:
    string name;
    int age;

public:
    Animal(string n, int a) : name(n), age(a) {}

    // Virtual function for polymorphism
    virtual void makeSound() {
        cout << "Some generic animal sound" << endl;
    }

    void sleep() {
        cout << name << " is sleeping" << endl;
    }

    // Virtual destructor for proper cleanup
    virtual ~Animal() {}
};

// Derived class - Single inheritance
class Dog : public Animal {
private:
    string breed;

public:
    Dog(string n, int a, string b) : Animal(n, a), breed(b) {}

    // Override base class method
    void makeSound() override {
        cout << name << " says: Woof! Woof!" << endl;
    }

    void fetch() {
        cout << name << " is fetching the ball" << endl;
    }
};

// Another derived class
class Cat : public Animal {
private:
    string color;

public:
    Cat(string n, int a, string c) : Animal(n, a), color(c) {}

    // Override base class method
    void makeSound() override {
        cout << name << " says: Meow! Meow!" << endl;
    }

    void climb() {
        cout << name << " is climbing a tree" << endl;
    }
};

// Multilevel inheritance
class Puppy : public Dog {
public:
    Puppy(string n, int a, string b) : Dog(n, a, b) {}

    void makeSound() override {
        cout << name << " says: Yip! Yip!" << endl;
    }
};

int main() {
    // Creating objects of different types
    Dog myDog("Buddy", 3, "Golden Retriever");
    Cat myCat("Whiskers", 2, "Gray");
    Puppy myPuppy("Max", 1, "Labrador");

    // Using inherited methods
    myDog.sleep();
    myCat.sleep();

    // Polymorphism in action
    Animal* animals[3];
    animals[0] = &myDog;
    animals[1] = &myCat;
    animals[2] = &myPuppy;

    cout << "\nPolymorphism demonstration:" << endl;
    for (int i = 0; i < 3; i++) {
        animals[i]->makeSound();  // Calls the appropriate version
    }

    // Specific class methods
    myDog.fetch();
    myCat.climb();

    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class BankAccount {
private:
    // Private data - hidden from outside
    string accountNumber;
    double balance;
    string ownerName;

public:
    // Constructor
    BankAccount(string accNum, string name, double initialBalance) {
        accountNumber = accNum;
        ownerName = name;
        if (initialBalance >= 0) {
            balance = initialBalance;
        } else {
            balance = 0;
            cout << "Initial balance cannot be negative! Set to 0." << endl;
        }
    }

    // Public getter methods - controlled access
    string getAccountNumber() {
        return accountNumber;
    }

    string getOwnerName() {
        return ownerName;
    }

    double getBalance() {
        return balance;
    }

    // Public setter methods with validation
    void setOwnerName(string newName) {
        if (!newName.empty()) {
            ownerName = newName;
            cout << "Owner name updated successfully." << endl;
        } else {
            cout << "Name cannot be empty!" << endl;
        }
    }

    // Business methods with controlled access
    void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            cout << "Deposited: $" << amount << endl;
            cout << "New balance: $" << balance << endl;
        } else {
            cout << "Deposit amount must be positive!" << endl;
        }
    }

    void withdraw(double amount) {
        if (amount > 0) {
            if (amount <= balance) {
                balance -= amount;
                cout << "Withdrawn: $" << amount << endl;
                cout << "New balance: $" << balance << endl;
            } else {
                cout << "Insufficient funds!" << endl;
            }
        } else {
            cout << "Withdrawal amount must be positive!" << endl;
        }
    }

    void displayAccountInfo() {
        cout << "\n=== Account Information ===" << endl;
        cout << "Account Number: " << getAccountNumber() << endl;
        cout << "Owner Name: " << getOwnerName() << endl;
        cout << "Balance: $" << getBalance() << endl;
        cout << "===========================" << endl;
    }
};

int main() {
    cout << "=== Bank Account Encapsulation Example ===" << endl;

    // Create account
    BankAccount myAccount("ACC123456", "Ali Khan", 1000.0);

    // Access data through getters
    cout << "\nInitial account info:" << endl;
    myAccount.displayAccountInfo();

    // Try to access private data directly (WON'T WORK)
    // cout << myAccount.balance; // ERROR: 'balance' is private

    // Use public methods to interact
    cout << "\n--- Performing Transactions ---" << endl;
    myAccount.deposit(500.0);
    myAccount.withdraw(200.0);

    // Try invalid withdrawal
    myAccount.withdraw(2000.0);

    // Update owner name
    cout << "\n--- Updating Information ---" << endl;
    myAccount.setOwnerName("Ali Ahmed Khan");

    // Try invalid name
    myAccount.setOwnerName("");

    // Display final info
    myAccount.displayAccountInfo();

    // Another example: Student class
    cout << "\n\n=== Student Class Example ===" << endl;

    class Student {
    private:
        string name;
        int age;
        double gpa;

    public:
        Student(string n, int a, double g) {
            name = n;
            setAge(a);  // Use setter for validation
            setGPA(g);  // Use setter for validation
        }

        // Getters
        string getName() { return name; }
        int getAge() { return age; }
        double getGPA() { return gpa; }

        // Setters with validation
        void setAge(int a) {
            if (a >= 0 && a <= 120) {
                age = a;
            } else {
                age = 0;
                cout << "Invalid age! Set to 0." << endl;
            }
        }

        void setGPA(double g) {
            if (g >= 0.0 && g <= 4.0) {
                gpa = g;
            } else {
                gpa = 0.0;
                cout << "Invalid GPA! Set to 0.0." << endl;
            }
        }

        void displayInfo() {
            cout << "Student: " << name << ", Age: " << age << ", GPA: " << gpa << endl;
        }
    };

    Student student1("Sara", 20, 3.8);
    student1.displayInfo();

    // Try invalid updates
    student1.setAge(150);  // Invalid
    student1.setGPA(5.0);  // Invalid
    student1.displayInfo();

    cout << "\n=== Benefits of Encapsulation ===" << endl;
    cout << "1. Data Protection: Private data can't be modified directly" << endl;
    cout << "2. Validation: Setters can validate input" << endl;
    cout << "3. Flexibility: Can change implementation without affecting users" << endl;
    cout << "4. Maintainability: Easier to debug and modify" << endl;

    return 0;
}

