    time_t now = time(0);
    cout << "\nCurrent timestamp: " << now << endl;
    cout << "Local time: " << ctime(&now);

    // Formatting date
    tm* localTime = localtime(&now);
    char buffer[80];
    strftime(buffer, 80, "%Y-%m-%d %H:%M:%S", localTime);
    cout << "Formatted: " << buffer << endl;

    // Measuring time
    clock_t start = clock();
    // Simulate some work
    for (int i = 0; i < 1000000; i++) {}
