    cout << endl;

    cout << "First element: " << cars.front() << endl;
    cout << "Last element: " << cars.back() << endl;
    cout << "Size: " << cars.size() << endl;

    // List demonstration
    cout << "\n=== LIST ===" << endl;
    list<string> animals = {"Dog", "Cat", "Elephant", "Lion"};

    // List operations
    animals.push_front("Tiger");   // Add to front
    animals.push_back("Bear");     // Add to back
    animals.pop_front();           // Remove from front

    cout << "List elements: ";
    for (const string& animal : animals) {
        cout << animal << " ";     // Sequential access only
    }
    cout << endl;

    cout << "First element: " << animals.front() << endl;
    cout << "Last element: " << animals.back() << endl;
    cout << "Size: " << animals.size() << endl;

    // Performance comparison
    cout << "\n=== PERFORMANCE ===" << endl;
    cout << "Vector: Fast random access, slow insert/delete in middle" << endl;
    cout << "List: Fast insert/delete anywhere, no random access" << endl;

    return 0;
}
